interface QuantityChangedDetail {
  variantId: string;
  quantity: number;
}

interface CartElement extends HTMLElement {
  changeItemQuantity: (variantId: string, quantity: number) => void;
}

import { refreshMiniCart } from "./minicart-sync";

document.addEventListener("quantityChanged", (event) => {
  const { variantId, quantity } = (event as CustomEvent<QuantityChangedDetail>)
    .detail;
  (document.querySelector("uwp-cart") as CartElement)?.changeItemQuantity(
    variantId,
    quantity,
  );
});

// Reload cart page and refresh minicart on cartUpdated
document.addEventListener("cartUpdated", () => {
  refreshMiniCart();
  if (document.body.classList.contains("template-cart"))
    window.location.reload();
});

// Toggle minicart drawer when header cart icon is clicked
document.addEventListener("click", (event) => {
  const anchor = (event.target as HTMLElement).closest(
    ".header__action--cart > a",
  ) as HTMLAnchorElement | null;
  if (!anchor) return;

  event.preventDefault();

  const minicart = document.querySelector("uwp-minicart");
  if (minicart) {
    minicart.setAttribute("open", "true");
    refreshMiniCart();
  }
});

// Delegate clicks on plus/minus inside minicart
document.addEventListener("click", (event) => {
  const target = event.target as HTMLElement;
  if (
    !target.classList.contains("minicart__item__increment") &&
    !target.classList.contains("minicart__item__decrement")
  ) {
    return;
  }

  const input = target.parentElement?.querySelector<HTMLInputElement>(
    ".minicart__item__quantity",
  );
  if (!input) return;

  const current = parseInt(input.value, 10) || 1;
  const max = parseInt(input.getAttribute("max") || "9999", 10);
  let next =
    current + (target.classList.contains("minicart__item__increment") ? 1 : -1);
  if (next < 1) next = 1;
  if (next > max) next = max;

  if (next === current) return;

  const variantId = input.dataset.id;
  if (!variantId) return;

  (document.querySelector("uwp-cart") as CartElement)?.changeItemQuantity(
    variantId,
    next,
  );
});
